1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import ScreenHeader from '$lib/components/ui/ScreenHeader.svelte';
4	  import Button from '$lib/components/ui/Button.svelte';
5	  import Spinner from '$lib/components/ui/Spinner.svelte';
6	  import DiffRow from '$lib/components/ui/DiffRow.svelte';
7	  import { truncateDid } from '$lib/did-doc-utils';
8	  import {
9	    buildRekey,
10	    submitRekey,
11	    ensureIdentitySession,
12	    sovereignLogin,
13	    isCodedError,
14	    type RekeyPreview,
15	    type RekeyResult,
16	    type RekeyError,
17	  } from '$lib/ipc';
18	
19	  let {
20	    did,
21	    onback,
22	    ondone,
23	  }: {
24	    did: string;
25	    onback: () => void;
26	    /** Called once the re-key lands — carries the new Share 3 for the backup step. */
27	    ondone: (result: RekeyResult) => void;
28	  } = $props();
29	
30	  type Phase =
31	    | { kind: 'loading' }
32	    | { kind: 'ready'; preview: RekeyPreview; error?: string }
33	    | { kind: 'load_error'; error: string }
34	    | { kind: 'working' };
35	
36	  let phase = $state<Phase>({ kind: 'loading' });
37	
38	  function messageFor(raw: unknown): string {
39	    if (!isCodedError(raw)) return 'Something went wrong. Please try again.';
40	    const err = raw as RekeyError;
41	    switch (err.code) {
42	      case 'NOT_DID_PLC':
43	        return 'This identity type doesn’t use a recovery key.';
44	      case 'ALREADY_REKEYED':
45	        return 'This identity already has a recovery key — nothing to upgrade.';
46	      case 'WALLET_NOT_AUTHORIZED':
47	        return 'This wallet isn’t the root key holder for this identity.';
48	      case 'SESSION_LOCKED':
49	        return 'Couldn’t unlock this identity. Please try again.';
50	      case 'RATE_LIMITED':
51	        return 'Too many attempts. Please wait a moment and try again.';
52	      case 'GUARD_REJECTED':
53	        return 'The upgrade was blocked by a safety check and was not signed.';
54	      case 'ESCROW_FAILED':
55	        return 'Couldn’t save your recovery share to the server. Please try again.';
56	      case 'SHARE_STORAGE_FAILED':
57	        return 'Your identity was upgraded, but saving the local backup failed. Please try again.';
58	      case 'PLC_SUBMISSION_FAILED':
59	        return 'The directory rejected the change. Please try again.';
60	      case 'PLC_DIRECTORY_ERROR':
61	        return 'The identity directory had a problem. Please try again shortly.';
62	      case 'SERVER_ERROR':
63	        return 'The server couldn’t complete this step. Please try again.';
64	      case 'NETWORK_ERROR':
65	        return 'Couldn’t reach the server. Check your connection.';
66	      default:
67	        return 'Something went wrong. Please try again.';
68	    }
69	  }
70	
71	  /** Run `fn` with the session pre-flight: unlock passwordlessly once if locked. */
72	  async function withUnlockedSession<T>(fn: () => Promise<T>): Promise<T> {
73	    try {
74	      await ensureIdentitySession(did);
75	    } catch (e) {
76	      if (isCodedError(e) && e.code === 'NEEDS_UNLOCK') {
77	        await sovereignLogin(did);
78	      } else {
79	        throw e;
80	      }
81	    }
82	    try {
83	      return await fn();
84	    } catch (e) {
85	      if (isCodedError(e) && e.code === 'SESSION_LOCKED') {
86	        await sovereignLogin(did);
87	        return await fn();
88	      }
89	      throw e;
90	    }
91	  }
92	
93	  async function build() {
94	    phase = { kind: 'loading' };
95	    try {
96	      const preview = await buildRekey(did);
97	      phase = { kind: 'ready', preview };
98	    } catch (e) {
99	      console.error('[RekeyReviewScreen] failed to build re-key:', e);
100	      phase = { kind: 'load_error', error: messageFor(e) };
101	    }
102	  }
103	
104	  async function submit() {
105	    if (phase.kind !== 'ready') return;
106	    const preview = phase.preview;
107	    phase = { kind: 'working' };
108	    try {
109	      const result = await withUnlockedSession(() => submitRekey(did));
110	      ondone(result);
111	    } catch (e) {
112	      console.error('[RekeyReviewScreen] re-key failed:', e);
113	      phase = { kind: 'ready', preview, error: messageFor(e) };
114	    }
115	  }
116	
117	  onMount(build);
118	</script>
119	
120	<div class="screen">
121	  <ScreenHeader title="Add a recovery key" onback={onback} backLabel="Back to identity" />
122	
123	  <p class="intro">
124	    This identity predates recovery keys. Adding one gives you a way back in if you lose this
125	    device — through your saved shares — without changing anything you rely on today. Your device
126	    key stays firmly in control, and nothing is removed.
127	  </p>
128	
129	  <div class="identity">
130	    <span class="id-label">Identity</span>
131	    <span class="id-did">{truncateDid(did)}</span>
132	  </div>
133	
134	  {#if phase.kind === 'loading'}
135	    <div class="center">
136	      <Spinner size={28} label="Preparing the upgrade" />
137	      <p class="hint">Generating your new recovery shares…</p>
138	    </div>
139	  {:else if phase.kind === 'load_error'}
140	    <p class="status" role="alert">{phase.error}</p>
141	    <Button onclick={build}>Try again</Button>
142	  {:else if phase.kind === 'working'}
143	    <div class="center">
144	      <Spinner size={28} label="Adding your recovery key" />
145	      <p class="hint">Publishing the change and saving your shares…</p>
146	    </div>
147	  {:else if phase.kind === 'ready'}
148	    <div class="block">
149	      <p class="block-label">This upgrade will</p>
150	      {#each phase.preview.diff.addedKeys as key}
151	        <DiffRow variant="restore" title="Add your new recovery key" value={key} />
152	      {/each}
153	      <p class="reassure">Nothing is removed. Your device key stays your root key.</p>
154	    </div>
155	
156	    <div class="sealed">
157	      <span class="sealed-ic" aria-hidden="true"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z" /><path d="m9 11.5 2 2 4-4" /></svg></span>
158	      Sealed by your device key
159	    </div>
160	
161	    {#if phase.error}
162	      <div class="error-box" role="alert">
163	        <p class="error-text">{phase.error}</p>
164	      </div>
165	    {/if}
166	
167	    <div class="actions">
168	      <Button onclick={submit}>Add recovery key</Button>
169	      <Button variant="secondary" onclick={onback}>Not now</Button>
170	    </div>
171	  {/if}
172	</div>
173	
174	<style>
175	  .screen {
176	    display: flex;
177	    flex-direction: column;
178	    gap: var(--space-md);
179	    padding: var(--space-md);
180	    height: 100%;
