1	import { invoke } from '@tauri-apps/api/core';
2	import { authenticateBiometric } from '$lib/biometric';
3	import type { OpDiff } from './claim';
4	import type { UnlockReason } from './identity';
5	
6	// ── Old-model re-key migration (MM-411) ───────────────────────────────────────
7	//
8	// Moves a pre-existing account off the voided server-generated split and onto the
9	// client-generated recovery model: generate a new seed, insert its recovery key at
10	// rotationKeys[1] via a device-key-signed PLC op (device stays [0], PDS shifts to [2]),
11	// escrow the new Share 2, rewrite the local Share 1, and walk the user through saving the
12	// new Share 3. Additive and resumable — see `rekey.rs`.
13	
14	/**
15	 * Error returned by the re-key flow. Matches `RekeyError` in `rekey.rs`
16	 * (`#[serde(tag = "code", rename_all = "SCREAMING_SNAKE_CASE", rename_all_fields = "camelCase")]`) —
17	 * codes must match exactly.
18	 *
19	 * `SESSION_LOCKED` is the cue to run the passwordless {@link sovereignLogin} (biometric) and
20	 * retry, exactly as in the rotation/migration flows.
21	 */
22	export type RekeyError =
23	  // The DID is a did:web identity — the recovery-key model does not apply.
24	  | { code: 'NOT_DID_PLC' }
25	  // The identity already carries a recovery key (new-model) — nothing to re-key.
26	  | { code: 'ALREADY_REKEYED' }
27	  // The wallet's device key is not rotationKeys[0], so it cannot additively re-key.
28	  | { code: 'WALLET_NOT_AUTHORIZED' }
29	  // The identity is locked — run sovereignLogin(did) and retry.
30	  | { code: 'SESSION_LOCKED'; reason: UnlockReason }
31	  | { code: 'RATE_LIMITED'; retryAfter: string | null }
32	  // The strict additive pre-sign guard rejected the op.
33	  | { code: 'GUARD_REJECTED'; reason: string }
34	  | { code: 'INVALID_AUDIT_LOG'; message: string }
35	  | { code: 'SHARE_GENERATION_FAILED'; message: string }
36	  | { code: 'SIGNING_FAILED'; message: string }
37	  | { code: 'PLC_SUBMISSION_FAILED'; message: string }
38	  // plc.directory answered a read with an HTTP failure (outage/verdict, not connectivity).
39	  | { code: 'PLC_DIRECTORY_ERROR'; message: string }
40	  // A server-side step failed for a non-connectivity reason (session refresh verdict,
41	  // unsupported host, malformed response, or session storage). Details in `message`.
42	  | { code: 'SERVER_ERROR'; message: string }
43	  | { code: 'ESCROW_FAILED'; status: number; message: string }
44	  | { code: 'SHARE_STORAGE_FAILED'; message: string }
45	  // Confirm was called before Share 1 reached its durable slot.
46	  | { code: 'SHARE_NOT_STORED' }
47	  | { code: 'NETWORK_ERROR'; message: string }
48	  | { code: 'IDENTITY_NOT_FOUND'; message: string };
49	
50	/**
51	 * Preview of a re-key, driving the review screen. Matches `RekeyPreview` in `rekey.rs`
52	 * (`#[serde(rename_all = "camelCase")]`).
53	 */
54	export interface RekeyPreview {
55	  /** The additive key diff — `addedKeys: [recovery]`, `removedKeys: []` (nothing is lost). */
56	  diff: OpDiff;
57	  /** The recovery `did:key` that will be inserted at rotationKeys[1]. */
58	  recoveryKeyId: string;
59	}
60	
61	/**
62	 * Result of a completed re-key. Matches `RekeyResult` in `rekey.rs`
63	 * (`#[serde(rename_all = "camelCase")]`).
64	 */
65	export interface RekeyResult {
66	  /** The refreshed DID document (PLC data shape) so the home card updates immediately. */
67	  updatedDidDoc: Record<string, unknown>;
68	  /** The new Share 3 envelope (base32/QR form) for the user to save. */
69	  share3: string;
70	  /** The new Share 3 rendered as the BIP-39-style word phrase. */
71	  share3Words: string;
72	}
73	
74	/**
75	 * Build the re-key preview: generate + stage the new recovery share set, prove the account is
76	 * an eligible old-model did:plc identity, and return the additive diff for review.
77	 *
78	 * Idempotent — the staged set is reused across retries. Signs nothing (submit does that).
79	 * Rejects with `SESSION_LOCKED` only downstream in {@link submitRekey}; build touches only the
80	 * public audit log.
81	 */
82	export const buildRekey = (did: string): Promise<RekeyPreview> => invoke('build_rekey_cmd', { did });
83	
84	/**
85	 * Run the re-key: post the additive rotation op (device-key-signed) to plc.directory, escrow
86	 * the new Share 2, overwrite the durable Share 1, and refresh the cache. Returns the new Share 3.
87	 *
88	 * The biometric prompt precedes the IPC invocation (the owner gate on an identity operation);
89	 * cancellation never reaches the network. Idempotent/resumable: a lost response or interrupted
90	 * run is healed by calling this again — every step converges on the same terminal state, and no
91	 * intermediate state drops recovery capability below the pre-re-key baseline.
92	 *
93	 * On `SESSION_LOCKED`, run {@link sovereignLogin} and retry.
94	 */
