1	// pattern: Imperative Shell
2	//! In-app, in-memory diagnostics: a small ring buffer of *redacted* network-error
3	//! breadcrumbs the user can export from Settings and hand to support for troubleshooting.
4	//!
5	//! Redaction is by construction. Every recorded field is safe to share: a call-site
6	//! operation name (a fixed vocabulary from the code, never request data), the server
7	//! hostname, an HTTP status, and a short error category or atproto error code. Bearer/DPoP
8	//! tokens, request/response bodies, handles, emails, and DIDs are never captured — so an
9	//! exported report can be shared without leaking account material. Nothing is written to
10	//! disk; the buffer lives for the process lifetime only, and the user initiates every
11	//! export, so there is no passive/always-on collection to opt out of.
12	
13	use std::collections::VecDeque;
14	use std::sync::{Mutex, OnceLock};
15	
16	/// Most breadcrumbs retained; the oldest are dropped FIFO once the buffer is full. Bounded
17	/// so a long session or a failing-server loop can never grow memory without limit.
18	const CAPACITY: usize = 200;
19	
20	/// Whether the failure was the server answering with an error status, or the request never
21	/// producing a usable answer (timeout, connection refused, DNS, a mid-read drop).
22	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
23	pub enum Origin {
24	    /// The server answered with a non-success HTTP status.
25	    Server,
26	    /// A transport failure — the request never yielded a server verdict.
27	    Transport,
28	}
29	
30	impl Origin {
31	    fn label(self) -> &'static str {
32	        match self {
33	            Origin::Server => "server",
34	            Origin::Transport => "transport",
35	        }
36	    }
37	}
38	
39	/// One redacted network-error breadcrumb. Construction is the only redaction gate: callers
40	/// pass structured, non-sensitive values, so there is no free-form field to leak through.
41	#[derive(Clone, Debug)]
42	struct NetworkEvent {
43	    /// RFC 3339 UTC, seconds precision.
44	    at: String,
45	    /// Call-site / operation name, e.g. `"createSession"`.
46	    op: String,
47	    /// Server hostname only — no path, query, or userinfo, e.g. `"plc.directory"`.
48	    host: Option<String>,
49	    origin: Origin,
50	    /// HTTP status, when the server answered.
51	    status: Option<u16>,
52	    /// A short, safe detail: a transport category (`"timeout"`, `"connect"`, …) or an
53	    /// atproto error code (`"RateLimited"`, `"InvalidRequest"`). Never a free-form body.
54	    detail: Option<String>,
55	}
56	
57	/// Process-global breadcrumb sink. A unit-of-global like `IdentityStore`: no state threads
58	/// through the deep network seams (`pds_client`, `plc_monitor`), which record via free
59	/// functions here without carrying a Tauri `State` handle.
60	fn sink() -> &'static Mutex<VecDeque<NetworkEvent>> {
61	    static SINK: OnceLock<Mutex<VecDeque<NetworkEvent>>> = OnceLock::new();
62	    SINK.get_or_init(|| Mutex::new(VecDeque::with_capacity(CAPACITY)))
63	}
64	
65	fn push(event: NetworkEvent) {
66	    // A poisoned lock must never crash a diagnostics write — recover the guard and continue.
67	    let mut buf = match sink().lock() {
68	        Ok(guard) => guard,
69	        Err(poisoned) => poisoned.into_inner(),
70	    };
71	    if buf.len() == CAPACITY {
72	        buf.pop_front();
73	    }
74	    buf.push_back(event);
75	}
76	
77	fn now_rfc3339() -> String {
78	    chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
79	}
80	
81	/// Record a server-verdict network error (the server answered with a non-2xx status).
82	/// `code` is the atproto error envelope's short `error` code, when present.
83	pub fn record_server(op: &str, host: Option<&str>, status: u16, code: Option<&str>) {
84	    push(NetworkEvent {
85	        at: now_rfc3339(),
86	        op: op.to_string(),
87	        host: host.map(str::to_string),
88	        origin: Origin::Server,
89	        status: Some(status),
90	        detail: code.map(str::to_string),
91	    });
92	}
93	
94	/// Record a transport failure (no usable server answer). `category` is a fixed, non-sensitive
95	/// label — use [`transport_category`] to derive one from a `reqwest::Error`.
96	pub fn record_transport(op: &str, host: Option<&str>, category: &str) {
97	    push(NetworkEvent {
98	        at: now_rfc3339(),
99	        op: op.to_string(),
100	        host: host.map(str::to_string),
101	        origin: Origin::Transport,
102	        status: None,
103	        detail: Some(category.to_string()),
104	    });
105	}
106	
107	/// Classify a `reqwest` transport error into a short, non-sensitive category. The error's
108	/// `Display` can embed the full request URL (host *and* query), so it is deliberately never
109	/// captured — only this fixed category is.
110	pub fn transport_category(e: &reqwest::Error) -> &'static str {
111	    if e.is_timeout() {
112	        "timeout"
113	    } else if e.is_connect() {
114	        "connect"
115	    } else if e.is_decode() || e.is_body() {
116	        "read"
117	    } else if e.is_request() {
118	        "request"
119	    } else {
120	        "other"
121	    }
122	}
123	
124	/// Render the recorded breadcrumbs into a shareable plain-text report.
125	pub fn export() -> String {
126	    let events: Vec<NetworkEvent> = {
127	        let buf = match sink().lock() {
128	            Ok(guard) => guard,
129	            Err(poisoned) => poisoned.into_inner(),
130	        };
131	        buf.iter().cloned().collect()
132	    };
133	
134	    let mut out = String::new();
135	    out.push_str("Obsign diagnostics — network events\n");
136	    out.push_str(&format!("Generated: {}\n", now_rfc3339()));
137	    out.push_str(
138	        "Contains operation names, server hostnames, HTTP statuses, and short error codes\n\
139	         only — no tokens, request/response bodies, handles, emails, or DIDs.\n\n",
140	    );
141	
142	    if events.is_empty() {
143	        out.push_str("No network errors have been recorded this session.\n");
144	        return out;
145	    }
146	
147	    out.push_str(&format!("{} event(s), oldest first:\n\n", events.len()));
148	    for e in &events {
149	        let at = &e.at;
150	        let origin = e.origin.label();
151	        let op = &e.op;
152	        let host = e.host.as_deref().unwrap_or("—");
153	        let status = e
154	            .status
155	            .map(|s| s.to_string())
156	            .unwrap_or_else(|| "—".to_string());
157	        let detail = e.detail.as_deref().unwrap_or("");
158	        out.push_str(&format!(
159	            "{at}  {origin:<9}  {op:<26}  {host:<20}  {status:>4}  {detail}\n"
160	        ));
161	    }
162	    out
163	}
164	
165	/// Tauri command: render the in-memory network-error breadcrumb log as plain text for the
166	/// user to share from Settings. Synchronous (no state, no I/O) — mirrors `list_identities`.
167	#[tauri::command]
168	pub fn export_diagnostics() -> String {
169	    export()
170	}
171	
172	#[cfg(test)]
173	mod tests {
174	    use super::*;
175	
176	    // The process-global sink is shared across tests in this binary (`RUST_TEST_THREADS=1`
177	    // keeps them serial). Each test records its own uniquely-named markers and asserts on
178	    // those, so leaked entries from a sibling test never affect the outcome.
179	
180	    #[test]
181	    fn export_reports_recorded_events() {
182	        record_server(
183	            "diag_test_login",
184	            Some("pds.example"),
185	            429,
186	            Some("RateLimited"),
187	        );
188	        record_transport("diag_test_discover", Some("plc.directory"), "timeout");
189	
190	        let report = export();
191	        assert!(report.contains("diag_test_login"));
192	        assert!(report.contains("429"));
193	        assert!(report.contains("RateLimited"));
194	        assert!(report.contains("pds.example"));
195	        assert!(report.contains("diag_test_discover"));
196	        assert!(report.contains("plc.directory"));
197	        assert!(report.contains("timeout"));
198	    }
199	
200	    #[test]
201	    fn report_header_promises_and_keeps_redaction() {
202	        // Even if a caller passed something token-ish as a detail, the report must not carry
203	        // obvious credential markers — the recorded vocabulary is codes and categories only.
204	        let report = export();
205	        assert!(report.to_lowercase().contains("no tokens"));
206	        assert!(!report.to_lowercase().contains("bearer "));
207	        assert!(!report.contains("Authorization:"));
208	    }
209	
210	    #[test]
211	    fn ring_buffer_is_bounded() {
212	        for _ in 0..(CAPACITY + 50) {
213	            record_transport("diag_test_spam", None, "connect");
214	        }
215	        let len = {
216	            let buf = match sink().lock() {
217	                Ok(guard) => guard,
218	                Err(poisoned) => poisoned.into_inner(),
219	            };
220	            buf.len()
221	        };
222	        assert!(len <= CAPACITY, "buffer grew past CAPACITY: {len}");
223	    }
224	
225	    #[test]
226	    fn transport_category_labels_are_stable() {
227	        // The label set the report and any consumer rely on. Constructing a real
228	        // `reqwest::Error` per kind is impractical here; this pins the vocabulary shape.
229	        for label in ["timeout", "connect", "read", "request", "other"] {
230	            record_transport("diag_test_labels", None, label);
231	        }
232	        let report = export();
233	        for label in ["timeout", "connect", "read", "request", "other"] {
234	            assert!(report.contains(label), "missing label {label}");
235	        }
236	    }
237	}
