impl PdsClient {
    /// Construct a new PdsClient with the default plc.directory URL.
    pub fn new() -> Self {
        Self {
            client: Client::builder()
                .timeout(Duration::from_secs(30))
                .build()
                .unwrap_or_else(|_| Client::new()),
            plc_directory_url: "https://plc.directory".to_string(),
        }
